id: SCR-013   kind: screen   name: Order placed
app: APP-002   module: MOD-003   screen_type: confirmation   surface: phone
roles: [ROL-001, ROL-006, ROL-007, ROL-009]
tiers: {purpose: default, regions: default, actions: default, states: default}
provenance: ["compass:SCR-013", "model:spec.scrn", "user:FTR-002"]
stories: [US-S002]
---
purpose: Confirms the order and shows its total, including the delivery fee, before payment.
route: {name: order_placed, path: "/order_placed/:order_id", params: [{name: order_id, type: id, source: ENT-006.id}], guard: [signed_in, role_has_access]}
reached_from: [SCR-012.save]   leads_to: [SCR-014]
regions:   # alphabetical by key; the order carries no meaning
  - {key: result, shape: key_values, what: what was done and what happens next, bind: [ENT-006.buyer_account, ENT-006.items, ENT-006.delivery_day, ENT-006.produce_total, ENT-006.delivery_fee], importance: primary}
actions:
  - {key: open_pay_for_order, importance: secondary, intent: navigate, what: go to Pay for order, effect: [go SCR-014]}
states:   # what each must communicate, not how
  - {kind: error, message: Something failed; say what happened in plain words and offer a retry.}
  - {kind: loading, message: Nothing to show yet; the user must still see that content is coming.}
  - {kind: not_found, message: The item does not exist or was removed; offer a way back.}
  - {kind: offline, message: "There is no network; show saved data, and say which actions are unavailable and why."}
  - {kind: success, message: What the user did worked; say what changed.}
copy_keys: [lib.common.error, lib.common.loading, lib.common.not_found, lib.common.offline, lib.common.success, scr_013.open_pay_for_order, scr_013.result_label, scr_013.title]
accessibility: every region and action has a text label that assistive technology can read
acceptance:
  - GIVEN the user has typical data and a working network WHEN the user uses Order placed for its main purpose THEN the main purpose is achieved and the result is confirmed in plain words
  - GIVEN the server fails when Order placed asks for data or sends a change WHEN the failure is received THEN the user is told in plain words that something went wrong, nothing is lost, and a retry is offered
  - GIVEN the device has no network while the user is on Order placed WHEN the user opens Order placed or acts on it THEN saved data is shown as possibly out of date, actions that need the network say so, and queued actions are sent when the network returns
  - GIVEN the user opens a link to Order placed and is signed out WHEN the app starts from the link THEN the user signs in first and then arrives at Order placed, not at the home screen
  - GIVEN the user changes the app language while Order placed is open WHEN the change is applied THEN all text on Order placed follows the new language, numbers and dates follow its formats, and the user's place and input are kept
mock: {profiles: [typical], hero: ["ENT-006:payment_pending", "ENT-006:placed"]}
confirm: [RUL-S015 payments pending result]

