---
id: SCR-008   kind: screen   name: Produce listing form
app: APP-001   module: MOD-002   screen_type: form   surface: phone
roles: [ROL-002, ROL-004, ROL-008]
tiers: {purpose: default, regions: default, actions: default, states: default}
provenance: ["compass:SCR-008", "model:spec.scrn", "user:FTR-004"]
stories: [US-S004]
---
purpose: Create a produce listing with quantity and price once the seller is approved to list.
route: {name: produce_listing_form, path: /produce_listing_form, params: [], guard: [signed_in, role_has_access]}
reached_from: [SCR-007.open_produce_listing_form]   leads_to: [SCR-016]
regions:   # alphabetical by key; the order carries no meaning
  - {key: details, shape: inputs, what: the details the user gives about the produce listing, bind: [ENT-003.produce_name, ENT-003.quantity_available, ENT-003.price, ENT-003.availability_period, ENT-003.seller_farmer, ENT-003.seller_fpo], importance: primary}
actions:
  - {key: cancel, importance: secondary, intent: cancel, what: leave without saving, effect: [stay]}
  - {key: save, importance: primary, intent: confirm, what: save the new produce listing, precondition: the required details are given; the form is in create mode, effect: [call OP-S012, go SCR-016], errors: [network, forbidden, validation_failed, conflict], flags: [idempotent]}
  - {key: save_changes, importance: secondary, intent: confirm, what: save the changes to the produce listing, precondition: an existing record is being edited, effect: [call OP-S013, go SCR-016], errors: [network, forbidden, validation_failed, conflict], flags: [idempotent]}
inputs:
  - {key: availability_period, type: text, required: True, source: ENT-003.availability_period}
  - {key: price, type: money, required: True, source: ENT-003.price}
  - {key: produce_name, type: text, required: True, source: ENT-003.produce_name}
  - {key: quantity_available, type: number, required: True, source: ENT-003.quantity_available}
  - {key: seller_farmer, type: choice, source: ENT-003.seller_farmer}
  - {key: seller_fpo, type: choice, source: ENT-003.seller_fpo}
states:   # what each must communicate, not how
  - {kind: "domain:conflict", message: The data changed elsewhere since it was loaded; show what changed and let the user choose.}
  - {kind: "domain:submitting", message: The form is being sent; it cannot be sent again meanwhile.}
  - {kind: "domain:validating", message: The input is being checked; the user can keep typing.}
  - {kind: "domain:validation_failed", message: A value breaks a rule; the message names the input and the rule.}
  - {kind: error, message: Something failed; say what happened in plain words and offer a retry.}
  - {kind: forbidden, message: The user's role may not see or do this; say so and where to go instead.}
  - {kind: loading, message: Nothing to show yet; the user must still see that content is coming.}
  - {kind: offline, message: "There is no network; show saved data, and say which actions are unavailable and why."}
  - {kind: success, message: What the user did worked; say what changed.}
copy_keys: [lib.common.error, lib.common.forbidden, lib.common.loading, lib.common.offline, lib.common.success, lib.form.domain.conflict, lib.form.domain.submitting, lib.form.domain.validating, lib.form.domain.validation_failed, scr_008.availability_period, scr_008.cancel, scr_008.details_label, scr_008.price, scr_008.produce_name, scr_008.quantity_available, scr_008.save, scr_008.save_changes, scr_008.seller_farmer, scr_008.seller_fpo, scr_008.title]
analytics: [produce_listing_confirmed]
accessibility: the result of save the new produce listing is announced to assistive technology
acceptance:
  - GIVEN the user has typical data and a working network WHEN the user uses Produce listing form for its main purpose THEN the main purpose is achieved and the result is confirmed in plain words
  - GIVEN the user gave a value that breaks a rule on Produce listing form WHEN the user submits or leaves the input THEN the problem is named next to the input in plain words, the input is kept, and nothing is sent
  - GIVEN the server fails when Produce listing form asks for data or sends a change WHEN the failure is received THEN the user is told in plain words that something went wrong, nothing is lost, and a retry is offered
  - GIVEN the device has no network while the user is on Produce listing form WHEN the user opens Produce listing form or acts on it THEN saved data is shown as possibly out of date, actions that need the network say so, and queued actions are sent when the network returns
  - GIVEN the user sends the same thing twice, by repeating it or by a slow connection WHEN the second request arrives THEN the thing is created once, and the user sees one clear result
  - GIVEN a signed-in farmer on Produce listing form WHEN they save the new produce listing THEN the change is saved and the person reaches SCR-016
  - GIVEN a signed-in farmer on Produce listing form and the request fails with validation failed WHEN they save the new produce listing THEN they stay here, see the reason in plain words and can try again or leave
mock: {profiles: [broken, typical], hero: ["ENT-003:available", "ENT-003:pending_review"]}
